    searchPlaces: {
        parameters: {
            query?: {
                /**
                 * @description Free-text substring of the place name and parent municipality.
                 *     Does not match catalog keys. PLZ hits require `q` to be only digits.
                 */
                q?: string;
                /** @description Field that `q` is matched against. Ignored when `q` is absent. */
                type?: components["schemas"]["SearchType"];
                /** @description Substring matched against the address and the label. */
                address?: string;
                /** @description Exact Amtlicher Gemeindeschlüssel (2–8 digits). */
                ags?: string;
                /** @description Exact PLZ5 or PLZ8. */
                plz?: string;
                /** @description Exact geo_key or catalog id. Reloads a stored place; not free-text. */
                geoKey?: string;
                /** @description Exact spatial grain. */
                grain?: components["schemas"]["Grain"];
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Matching hits, at most 50, ordered by label. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "hits": [
                     *         {
                     *           "id": "1",
                     *           "label": "München",
                     *           "grain": "ags",
                     *           "geoKey": "09162000",
                     *           "lon": null,
                     *           "lat": null
                     *         }
                     *       ]
                     *     }
                     */
                    "application/json": components["schemas"]["SearchResponse"];
                };
            };
            400: components["responses"]["BadRequest"];
            401: components["responses"]["Unauthorized"];
        };
    };
